local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["6606245ecb6f4220"] = { "Quando la S.P.R. & Co. mi ha lasciato in fin di vita nelle ⟦Barrens=Savane⟧, è stato Mathias a trovarmi. Senza di lui, ora sarei cibo per i predatori.", "." },
  ["6607c10dbe4631a9"] = { "Sì, consegnerò gli ordini al maestro di guerra Garrick!", "." },
  ["660fac026228275f"] = { "Cosa hai da vendere?", "." },
  ["660ffc78fa691b37"] = { "<Poso la mano sulla sfera.>", "." },
  ["6616e74c187a7166"] = { "Vedo del potenziale in te, {name}. Ora prendi un martello e un po' di quei rottami: ti serve un sacco di pratica.", "." },
  ["661dcc2dc3e14f2f"] = { "È la mia fine! Evocate Verog!", "." },
  ["662461e3c0b16b41"] = { "Ah, come dice il titolo, faccio l'assassino per la ⟦Scarlet Crusade=Crociata Scarlatta⟧. Passo le giornate a sterminare bersagli di alta priorità e le notti nella discoteca di ⟦Gadgetzan=Meccania⟧. Ballare è la mia vera vocazione. Assassinare serve solo a pagare i conti.", "." },
  ["6627ff465d91cdbf"] = { "Lui nome è Grizzle Halfmane. Lui in Royal Quarter con Regina Banshee e Dread Lord.", "." },
  ["66306e06def4f901"] = { "Che succede? Guarda!", "." },
  ["6669a1858bab991c"] = { "Uccideteli, fratelli miei! Per il Flagello!", "." },
  ["666a6c781bb8fae4"] = { "Direi che avevi fame! Trok avrebbe dovuto darti da mangiare prima... Cosa avrà combinato per tutto questo tempo?", "." },
  ["666c588f8507c742"] = { "Buona fortuna, {name}. E non dimenticare... prendi quel documento prima di cercare Gazin.", "." },
  ["666dcc97c67e3d3e"] = { "Maestro di guerra, ho perso le mie insegne. Potresti darmene di nuove?", "." },
  ["666ffda18db67ee6"] = { "Hai visto Petra o Dadanga da queste parti?", "." },
  ["667116afb686a9f0"] = { "Il gran signore era il fulcro della Crociata. Sì, Mograine era chiamato il Brandicenere per le sue imprese contro le armate del Re dei Lich. Armato solo della sua lama e della sua fede, Mograine marciava contro interi battaglioni di non morti e ne usciva illeso: le ceneri dei suoi nemici erano l'unico segno del suo passaggio. Non capisci? Il volto stesso della morte lo temeva! Tremava in sua presenza!", "." },
  ["6672b2d113ec6784"] = { "Le rovine di ⟦Zul'Farrak=Zul'farrak⟧ si trovano nell'angolo nord-occidentale del deserto di Tanaris.", "." },
  ["66759634a95e747a"] = { "Se vai alla ⟦Cenarion Hold=Fortezza Cenariana⟧, a ⟦Silithus=Silitus⟧, troverai l'anziano Bladesing.", "." },
  ["6678b679bff41e19"] = { "Brzzzzt!\n\nBenvenuto nel Matrix Punchograph 3005 barra C, un terminale con livello di sicurezza chi.\n\nDevi possedere una scheda perforata blu per accedere alle funzioni del terminale.\n\n01010010 01100101 01100011 01101001 01110000 01100101 00111010 00100000 01001101 01100101 01100011 01101000 01100001 01101110 01101001 01100011 01100001 01101100 00100000 01000011 01101000 01101001 01100011 01101011 01100101 01101110 00100000 01010011 01101111 01110101 01110000", "." },
  ["667fb183fa51ecca"] = { "Arthur Moore in anello interno di ⟦Rogues' Quarter=Quartiere dei Ladri⟧ è uno che insegna conciatura.", "." },
  ["6680dc1d788ade0e"] = { "Parlami di nuovo delle miniere...", "." },
  ["66838604ab8c3c97"] = { "Non ne posso più di correre, ma queste api non mi lasciano in pace!", "." },
  ["66873924bffae4c5"] = { "Falthir, ho perso i miei ⟦Zandalar Predator's Mantle=Coprispalle del Predatore degli Zandalari⟧ e me ne servono di nuovi.", "." },
  ["668b6a2c9aae3a96"] = { "Impossibile! Fermate l'attacco, mortali... Mi arrendo! Mi arrendo!", "." },
  ["66911f5294c72ece"] = { "Nell'ultima guerra, i tauren combatterono. Gli Sciamani furono mandati a difendere questo mondo dall'invasione del Flagello. La maggior parte perse la vita. Molti altri furono fatti a pezzi, e le loro membra usate per orribili esperimenti in quella cittadella maledetta. Piango la loro scomparsa, ma il mio cuore si gonfia d'orgoglio per il loro coraggio.", "." },
  ["6694f6eaf89d7f1e"] = { "Prendo un focus per incantesimi qui in casa mia, e poi cominciamo!", "." },
  ["66a8d9079b9836ed"] = { "Gli dei primordiali servono Hakkar. Torna indietro ora, non hai alcuna speranza.", "." },
  ["66ac24e4e0701c71"] = { "Puoi lasciarmi qui... Desidero restare in solitudine nei miei ultimi istanti.", "." },
  ["66b1234742fd8acb"] = { "E ora persino le nazioni che avresti chiamato alleate si sono ritratte e hanno unito le forze con noi... Sì, vecchio, non fare quella faccia sorpresa.", "." },
  ["66b5785f8ba0b825"] = { "Già, hai l'aria di chi sa comandare. Sei qui per fondare una gilda che combatta per l'⟦Alliance=Alleanza⟧?", "." },
  ["66bd6d22345c5332"] = { "Che il sangue versato qui oggi sia una lezione per chiunque osi invadere il territorio del clan ⟦Blackrock=Roccianera⟧!", "." },
  ["66bd704a97a2782e"] = { "Deve essercene uno da qualche parte qui intorno...", "." },
  ["66c0c7f350dfd419"] = { "Devi essere in buoni rapporti con i nani di ⟦Ironforge=Forgiardente⟧ prima che io ti insegni a cavalcare, {class}.", "." },
  ["66c41a9024ec67ff"] = { "È ora di morire, {class}.", "." },
  ["66cce9c8f7aecb1d"] = { "Gliel'abbiamo fatta vedere!", "." },
  ["66cd13d8c4539d2d"] = { "Ho bisogno di addestramento, Grimnur.", "." },
  ["66d09dd52c23e2ff"] = { "L'anziano Ironband vive nella ⟦Blackchar Cave=Caverna Bracenera⟧, nella ⟦Searing Gorge=Gorgia Rovente⟧.", "." },
  ["66d878ae46c38c8f"] = { "Ehi, {class}! Pare che l'⟦Horde=Orda⟧ abbia raccolto le ultime cose, e ora la sua roba e la nostra vengono spedite a ⟦Silithus=Silitus⟧ proprio in questo momento. Mi dicono che arriveranno in meno di $2113w giorni, e poi qualcuno potrà suonare quel grande gong vicino alle porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧ per far cominciare la guerra.", "." },
  ["66e4713bbf324396"] = { "Non voltare le spalle alla Luce, {class}: un giorno potrebbe essere l'unica cosa a salvarti.", "." },
  ["66ea9434c533f35f"] = { "Cos'è questo? Una scheggiatura nel frammento? Finalmente, una debolezza scoperta... Non manca molto, ormai.", "." },
  ["66eddf21c2efbd82"] = { "Quando torna papà dai combattimenti a ⟦Warsong=Cantaguerra⟧? È passato così tanto tempo...", "." },
  ["66ee47154d89a88a"] = { "Posso averlo, per favore?", "." },
  ["66ef8197471d4e0e"] = { "Ce l'abbiamo fatta! Grazie, {name}. Senza di te non ce l'avrei mai fatta.", "." },
  ["66fc4134a5a6ad27"] = { "Mi attaccano! Aiutatemi a togliermi di dosso questo {name}!", "." },
})
